-- =====================================================================
-- Video 348: How I Redesigned a Database With 2,241 Tables
-- Script 2 of 4: The new schema
--
-- 3 tables replace the 2,241 client_ tables: client, study, enrolment.
-- Run after Script 1, in the same database. PostgreSQL 12+.
-- =====================================================================

-- One row per client. Every value that was inside the JSON gets its own
-- column. date_of_birth is a DATE, so nothing needs to update it.
-- GENERATED BY DEFAULT lets the migration keep the existing client IDs.
CREATE TABLE client (
  client_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name VARCHAR(100) NOT NULL,
  last_name VARCHAR(100) NOT NULL,
  date_of_birth DATE NOT NULL,
  sex VARCHAR(20),
  email VARCHAR(255) UNIQUE,
  phone VARCHAR(30),
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- Each research study is stored once
CREATE TABLE study (
  study_id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  study_code VARCHAR(20) NOT NULL UNIQUE,
  study_name VARCHAR(200) NOT NULL
);

-- Joining table: which clients are in which studies
CREATE TABLE enrolment (
  client_id INT NOT NULL REFERENCES client (client_id) ON DELETE CASCADE,
  study_id INT NOT NULL REFERENCES study (study_id),
  enrolled_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL,
  PRIMARY KEY (client_id, study_id)
);

-- Indexes on the columns the application searches by.
-- The enrolment primary key already covers lookups by client_id.
CREATE INDEX ix_client_last_name ON client (last_name);
CREATE INDEX ix_client_date_of_birth ON client (date_of_birth);
CREATE INDEX ix_enrolment_study ON enrolment (study_id);
